class Solution {
    int n, best, cap;
    vector<int> t_, loads;

    void dfs(int i, int used) {
        if (used >= best) return;
        if (i == n) {
            best = used;
            return;
        }
        unordered_set<int> tried;
        for (int j = 0; j < used; ++j) {
            if (loads[j] + t_[i] > cap || !tried.insert(loads[j]).second) continue;
            loads[j] += t_[i];
            dfs(i + 1, used);
            loads[j] -= t_[i];
        }
        loads[used] = t_[i];
        dfs(i + 1, used + 1);
    }

public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        cap = sessionTime;
        t_ = tasks;
        sort(t_.rbegin(), t_.rend());
        n = t_.size();
        best = n;
        loads.assign(n, 0);
        dfs(0, 0);
        return best;
    }
};

