class Solution {
    private int[] t_, loads;
    private int best;

    public int minSessions(int[] tasks, int sessionTime) {
        t_ = tasks.clone();
        Arrays.sort(t_);
        for (int l = 0, r = t_.length - 1; l < r; l++, r--) {
            int tmp = t_[l];
            t_[l] = t_[r];
            t_[r] = tmp;
        }
        loads = new int[t_.length];
        best = t_.length;
        dfs(0, 0, sessionTime);
        return best;
    }

    private void dfs(int i, int used, int cap) {
        if (used >= best) return;
        if (i == t_.length) {
            best = used;
            return;
        }
        Set<Integer> tried = new HashSet<>();
        for (int j = 0; j < used; ++j) {
            if (loads[j] + t_[i] > cap || !tried.add(loads[j])) continue;
            loads[j] += t_[i];
            dfs(i + 1, used, cap);
            loads[j] -= t_[i];
        }
        loads[used] = t_[i];
        dfs(i + 1, used + 1, cap);
    }
};

