var minSessions = function (tasks, sessionTime) {
    tasks.sort((a, b) => b - a);
    const n = tasks.length;
    const loads = [];
    let best = n;
    const dfs = (i) => {
        if (loads.length >= best) return;
        if (i === n) {
            best = loads.length;
            return;
        }
        const tried = new Set();
        for (let j = 0; j < loads.length; j++) {
            if (loads[j] + tasks[i] > sessionTime || tried.has(loads[j])) continue;
            tried.add(loads[j]);
            loads[j] += tasks[i];
            dfs(i + 1);
            loads[j] -= tasks[i];
        }
        loads.push(tasks[i]);
        dfs(i + 1);
        loads.pop();
    };
    dfs(0);
    return best;
};

