class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        FULL = (1 << n) - 1
        sm = [0] * (FULL + 1)
        for m in range(1, FULL + 1):
            lb = m & -m
            sm[m] = sm[m ^ lb] + tasks[lb.bit_length() - 1]
        INF = (float("inf"), 0)
        dp = [INF] * (FULL + 1)
        dp[0] = (0, sessionTime)
        for m in range(1, FULL + 1):
            bs, bt = INF
            sub = m
            while sub:
                if sm[sub] <= sessionTime:
                    ps, pt = dp[m ^ sub]
                    pt += sm[sub]
                    if pt > sessionTime:
                        ps, pt = ps + 1, sm[sub]
                    if (ps, pt) < (bs, bt):
                        bs, bt = ps, pt
                sub = (sub - 1) & m
            dp[m] = (bs, bt)
        return dp[FULL][0]

