class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size(), FULL = (1 << n) - 1;
        vector<int> sm(1 << n, 0);
        for (int m = 1; m <= FULL; ++m) {
            int lb = m & -m;
            sm[m] = sm[m ^ lb] + tasks[__builtin_ctz(m)];
        }
        pair<int, int> BAD = {INT_MAX / 2, 0};
        vector<pair<int, int>> dp(1 << n, BAD);
        dp[0] = {0, sessionTime};
        for (int m = 1; m <= FULL; ++m) {
            pair<int, int> best = BAD;
            for (int sub = m; sub; sub = (sub - 1) & m) {
                if (sm[sub] > sessionTime) continue;
                auto [ps, pt] = dp[m ^ sub];
                pair<int, int> cand =
                    (pt + sm[sub] <= sessionTime) ? make_pair(ps, pt + sm[sub])
                                                  : make_pair(ps + 1, sm[sub]);
                best = min(best, cand);
            }
            dp[m] = best;
        }
        return dp[FULL].first;
    }
};

