class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length, FULL = (1 << n) - 1;
        int[] sm = new int[1 << n];
        for (int m = 1; m <= FULL; ++m) {
            int lb = m & -m;
            sm[m] = sm[m ^ lb] + tasks[Integer.numberOfTrailingZeros(lb)];
        }
        int[][] dp = new int[1 << n][2];
        for (int m = 1; m <= FULL; ++m) {
            dp[m][0] = Integer.MAX_VALUE / 2;
            dp[m][1] = 0;
        }
        dp[0] = new int[]{0, sessionTime};
        for (int m = 1; m <= FULL; ++m) {
            int bs = Integer.MAX_VALUE / 2, bt = 0;
            for (int sub = m; sub > 0; sub = (sub - 1) & m) {
                if (sm[sub] > sessionTime) continue;
                int ps = dp[m ^ sub][0], pt = dp[m ^ sub][1] + sm[sub];
                if (pt > sessionTime) {
                    ++ps;
                    pt = sm[sub];
                }
                if (ps < bs || (ps == bs && pt < bt)) {
                    bs = ps;
                    bt = pt;
                }
            }
            dp[m][0] = bs;
            dp[m][1] = bt;
        }
        return dp[FULL][0];
    }
};

