            const p = dp[m ^ sub];
            let ps = p[0], pt = p[1] + sm[sub];
            if (pt > sessionTime) {
                ps++;
                pt = sm[sub];
            }
            if (ps < bs || (ps === bs && pt < bt)) {
                bs = ps;
                bt = pt;
            }
        }
        dp[m] = [bs, bt];
    }
    return dp[FULL][0];
